import{_ as a,C as i,c as o,o as s,al as r,G as n}from"./chunks/framework.BfTuqGjy.js";const v=JSON.parse('{"title":"Set up the demo","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://pointw-dev.github.io/hypermedia-docs/introduction/hypermedia-in-action/setup-the-demo.html"}]]},"headers":[],"relativePath":"introduction/hypermedia-in-action/setup-the-demo.md","filePath":"introduction/hypermedia-in-action/setup-the-demo.md"}'),d={name:"introduction/hypermedia-in-action/setup-the-demo.md"};function l(h,e,c,p,u,m){const t=i("comments-section");return s(),o("div",null,[e[0]||(e[0]=r('<h1 id="set-up-the-demo" tabindex="-1">Set up the demo <a class="header-anchor" href="#set-up-the-demo" aria-label="Permalink to &quot;Set up the demo&quot;">​</a></h1><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><p>To run this demo you will need:</p><ul><li>Docker</li><li>Python</li><li>git</li><li>(optional) Postman, cURL, or other API calling tool</li><li>(optional) VSCode, or other IDE or text editor</li></ul><h2 id="clone-the-repo" tabindex="-1">Clone the repo <a class="header-anchor" href="#clone-the-repo" aria-label="Permalink to &quot;Clone the repo&quot;">​</a></h2><p>You can clone the demo <a href="https://github.com/pointw-dev/hypermedia-demo" target="_blank" rel="noreferrer">from GitHub</a>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/pointw-dev/hypermedia-demo.git</span></span></code></pre></div><p>The repo contains both a server and clients in the following folders:</p><table tabindex="0"><thead><tr><th>Folder</th><th>Description</th></tr></thead><tbody><tr><td>server/</td><td></td></tr><tr><td>└─reset.py</td><td>Resets the data stored in the service. Run this before running any other clients for the first time, and any time thereafter to start the scenario over.</td></tr><tr><td>└─v1/</td><td>This folder contains the initial version of Event Buddy, released as a single service.</td></tr><tr><td>└─v2/</td><td>This folder contains a version of Event Buddy that provides the same data and capabilities as v1, but its architecture has been refactored. This will be described in further detail in an upcoming section.</td></tr><tr><td>clients/</td><td></td></tr><tr><td>└─alice/</td><td>This folder contains a client that uses Event Buddy following hypermedia. Works with Event Buddy v1, v2 and any future version as long as it stays committed to the hypermedia approach.</td></tr><tr><td>└─bob/</td><td>This folder contains a client built to use Event Buddy v1, implemented with knowledge of the service architecture.</td></tr><tr><td>└─bob-v2/</td><td>This folder contains an updated version of the v1 client built to use Event Buddy v2, implemented with knowledge of the service architecture</td></tr></tbody></table><h2 id="install-packages" tabindex="-1">Install packages <a class="header-anchor" href="#install-packages" aria-label="Permalink to &quot;Install packages&quot;">​</a></h2><p>In the repo folder, create a Python virtual environment called <code>hypermedia-demo</code> (or any name you wish). This step is optional but highly recommended.</p><p>Install <a href="https://github.com/pointw-dev/halchemy" target="_blank" rel="noreferrer">halchemy</a>, which is used by the <code>reset.py</code> script.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> halchemy</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title"><i></i></p><p>Installing halchemy also installs the <a href="https://requests.readthedocs.io/en/latest/" target="_blank" rel="noreferrer">requests</a> library. Both the <code>alice</code> client and the <code>bob</code> client use this - to keep the comparison between the two apples-to-apples.</p></div>',14)),n(t,{repo:"pointw-dev/hypermedia-docs",repoId:"R_kgDOODT1fw",category:"General",categoryId:"DIC_kwDOODT1f84CoFLx"})])}const y=a(d,[["render",l]]);export{v as __pageData,y as default};
